# Compute count of column 'Driver' grouped by 'Car'
print(f"🔧 Computing count of 'Driver' grouped by 'Car'")

# Check if columns exist and operation is valid
if 'Driver' not in df.columns:
    print(f"❌ Error: Column 'Driver' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Car' not in df.columns:
    print(f"❌ Error: Group by column 'Car' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Car')['Driver'].count()
        elif "count" == "sum":
            result = df.groupby('Car')['Driver'].sum()
        elif "count" == "avg":
            result = df.groupby('Car')['Driver'].mean()
        elif "count" == "min":
            result = df.groupby('Car')['Driver'].min()
        elif "count" == "max":
            result = df.groupby('Car')['Driver'].max()

        print(f"✅ Count of 'Driver' by 'Car':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Car', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Driver', 'Car']].dtypes}")
